window.TIMELINE = {"fps": 30, "transition": 18, "total": 10917, "scenes": [{"id": "open", "chapter": "", "from": 0, "len": 775, "segs": [{"k": 0, "at": 102, "len": 146, "text": "If an AI can do a piece of work for a few cents, why would anyone pay a person to do it?", "say": "If an AI can do a piece of work for a few cents, why would anyone pay a person to do it?"}, {"k": 1, "at": 259, "len": 284, "text": "Why Pay Anyone? is an economics project on cheap intelligence, carried out as a Lab Based Project at IIT Roorkee with Hello Agentic.", "say": "Why Pay Anyone? is an economics project on cheap intelligence, carried out as a Lab Based Project at IIT Roorkee with Hello Agentic."}, {"k": 2, "at": 554, "len": 186, "text": "It asks what happens to jobs, wages, prices and market power when intelligence becomes cheap.", "say": "It asks what happens to jobs, wages, prices and market power when intelligence becomes cheap."}]}, {"id": "ceiling", "chapter": "The idea", "from": 757, "len": 992, "segs": [{"k": 0, "at": 27, "len": 68, "text": "The starting point is a wage ceiling.", "say": "The starting point is a wage ceiling."}, {"k": 1, "at": 106, "len": 244, "text": "For any task an AI can also do, no employer will pay a person more than the AI would cost, allowing for how productive each one is.", "say": "For any task an AI can also do, no employer will pay a person more than the AI would cost, allowing for how productive each one is."}, {"k": 2, "at": 361, "len": 120, "text": "As the price of AI falls, that ceiling falls with it.", "say": "As the price of AI falls, that ceiling falls with it."}, {"k": 3, "at": 485, "len": 106, "text": "Whether people still earn well then depends on four things:", "say": "Whether people still earn well then depends on four things:"}, {"k": 4, "at": 595, "len": 110, "text": "comparative advantage while computing power is scarce,", "say": "comparative advantage while computing power is scarce,"}, {"k": 5, "at": 709, "len": 102, "text": "the new tasks that cheap intelligence creates,", "say": "the new tasks that cheap intelligence creates,"}, {"k": 6, "at": 815, "len": 86, "text": "whether demand holds up when wage income falls,", "say": "whether demand holds up when wage income falls,"}, {"k": 7, "at": 912, "len": 46, "text": "and who owns the AI.", "say": "and who owns the AI."}]}, {"id": "plan", "chapter": "The approach", "from": 1731, "len": 546, "segs": [{"k": 0, "at": 27, "len": 190, "text": "The project tests these ideas in six steps, each built on real data and one standard economic model.", "say": "The project tests these ideas in six steps, each built on real data and one standard economic model."}, {"k": 1, "at": 228, "len": 174, "text": "Price, use, adoption, a labour model, market power, and the macroeconomy.", "say": "Price, use, adoption, a labour model, market power, and the macroeconomy."}, {"k": 2, "at": 413, "len": 98, "text": "An India lens then uses government survey microdata.", "say": "An India lens then uses government survey microdata."}]}, {"id": "price", "chapter": "Chapter 1. The price of intelligence", "from": 2259, "len": 1313, "segs": [{"k": 0, "at": 27, "len": 40, "text": "Step one is the price.", "say": "Step one is the price."}, {"k": 1, "at": 78, "len": 436, "text": "Matching Epoch AI's capability scores to three years of list prices, the cheapest model at about GPT-4 level fell from $37.50 per million tokens in September 2023 to about 3 cents in November 2026.", "say": "Matching Epoch AI's capability scores to three years of list prices, the cheapest model at about GPT-4 level fell from thirty-seven dollars fifty per million tokens in September 2023, to about three cents in November 2026."}, {"k": 2, "at": 525, "len": 110, "text": "That price halves roughly every 3.8 months.", "say": "That price halves roughly every 3.8 months."}, {"k": 3, "at": 646, "len": 250, "text": "Did spending rise as prices fell, as Jevons found for coal? Token volumes on OpenRouter grew about 480 times.", "say": "Did spending rise as prices fell, as Jevons found for coal? Token volumes on Open Router grew about four hundred and eighty times."}, {"k": 4, "at": 907, "len": 312, "text": "But when one model cuts its price, the estimated elasticity is about \u22120.47, and its interval includes both zero and \u22121.", "say": "But when one model cuts its price, the estimated elasticity is about minus zero point four seven, and its interval includes both zero and minus one."}, {"k": 5, "at": 1230, "len": 48, "text": "So the data cannot yet settle it.", "say": "So the data cannot yet settle it."}]}, {"id": "use", "chapter": "Chapter 2. Where AI is used", "from": 3554, "len": 828, "segs": [{"k": 0, "at": 27, "len": 90, "text": "Step two asks where AI is used.", "say": "Step two asks where AI is used."}, {"k": 1, "at": 128, "len": 404, "text": "Two independent measures, Microsoft's Copilot scores and Anthropic's Claude usage, rank 591 US occupations with a correlation of 0.45, and whole job families with 0.80.", "say": "Two independent measures, Microsoft's Copilot scores and Anthropic's Claude usage, rank five hundred and ninety-one US occupations with a correlation of zero point four five, and whole job families with zero point eight."}, {"k": 2, "at": 543, "len": 176, "text": "Computer and mathematical jobs are 3% of US employment but nearly a quarter of usage.", "say": "Computer and mathematical jobs are three percent of US employment, but nearly a quarter of usage."}, {"k": 3, "at": 730, "len": 64, "text": "Exposure is real, but concentrated.", "say": "Exposure is real, but concentrated."}]}, {"id": "adoption", "chapter": "Chapter 3. Adoption in the economy", "from": 4364, "len": 1042, "segs": [{"k": 0, "at": 27, "len": 100, "text": "Step three asks whether it shows up in the economy.", "say": "Step three asks whether it shows up in the economy."}, {"k": 1, "at": 138, "len": 166, "text": "The share of US firms using AI rose from 17 to 25 percent in a year.", "say": "The share of US firms using AI rose from 17 to 25 percent in a year."}, {"k": 2, "at": 315, "len": 342, "text": "In Indeed job postings, the most exposed third of job categories has about 24 percent fewer postings than the least exposed third, relative to 2022.", "say": "In Indeed job postings, the most exposed third of job categories has about 24 percent fewer postings than the least exposed third, relative to 2022."}, {"k": 3, "at": 668, "len": 274, "text": "But the event study shows the gap opening before ChatGPT launched, as interest rates rose and the pandemic hiring boom ended.", "say": "But the event study shows the gap opening before ChatGPT launched, as interest rates rose and the pandemic hiring boom ended."}, {"k": 4, "at": 953, "len": 54, "text": "It is a pattern, not proof.", "say": "It is a pattern, not proof."}]}, {"id": "model", "chapter": "Chapter 4. The labour model", "from": 5388, "len": 1321, "segs": [{"k": 0, "at": 27, "len": 156, "text": "Step four is the core model, a task-based model in the spirit of Acemoglu and Restrepo.", "say": "Step four is the core model, a task-based model in the spirit of Acemoglu and Restrepo."}, {"k": 1, "at": 194, "len": 228, "text": "People are relatively better at some tasks, AI at others, and each task goes to whichever is cheaper.", "say": "People are relatively better at some tasks, AI at others, and each task goes to whichever is cheaper."}, {"k": 2, "at": 433, "len": 198, "text": "When firms adopt AI freely, the real wage in this model does not fall, but the labour share does.", "say": "When firms adopt AI freely, the real wage in this model does not fall, but the labour share does."}, {"k": 3, "at": 642, "len": 104, "text": "The price of AI matters only while it is high.", "say": "The price of AI matters only while it is high."}, {"k": 4, "at": 757, "len": 284, "text": "Once AI is cheaper on every task it can do, what matters is how much it can do, and whether tasks substitute or complement.", "say": "Once AI is cheaper on every task it can do, what matters is how much it can do, and whether tasks substitute or complement."}, {"k": 5, "at": 1052, "len": 234, "text": "Even a million tokens for an hour of work cost well under 1 percent of average US pay, so the token price itself is rarely what binds.", "say": "Even a million tokens for an hour of work cost well under one percent of average US pay, so the token price itself is rarely what binds."}]}, {"id": "market", "chapter": "Chapter 5. Market structure and power", "from": 6691, "len": 915, "segs": [{"k": 0, "at": 27, "len": 92, "text": "Step five asks who sells the intelligence.", "say": "Step five asks who sells the intelligence."}, {"k": 1, "at": 130, "len": 366, "text": "From daily token shares, the Herfindahl\u2013Hirschman index fell from about 3,070 in January 2025 to 990 in April 2026, then rose to about 1,580 by October.", "say": "From daily token shares, the Herfindahl Hirschman index fell from about three thousand and seventy in January 2025, to nine hundred and ninety in April 2026, then rose to about fifteen hundred and eighty by October."}, {"k": 2, "at": 507, "len": 126, "text": "The leading firm changed five times in 23 months.", "say": "The leading firm changed five times in 23 months."}, {"k": 3, "at": 644, "len": 236, "text": "And for open-weights models, doubling the number of hosts goes with a price about 29 percent lower, as Bertrand competition predicts.", "say": "And for open-weights models, doubling the number of hosts goes with a price about 29 percent lower, as Bertrand competition predicts."}]}, {"id": "macro", "chapter": "Chapter 6. Macroeconomics and policy", "from": 7588, "len": 992, "segs": [{"k": 0, "at": 27, "len": 52, "text": "Step six is the macroeconomy.", "say": "Step six is the macroeconomy."}, {"k": 1, "at": 90, "len": 288, "text": "In a Solow growth model with AI capital, calibrated to the Penn World Table, the labour share falls only if compute substitutes for labour, with an elasticity above one.", "say": "In a Solow growth model with AI capital, calibrated to the Penn World Table, the labour share falls only if compute substitutes for labour, with an elasticity above one."}, {"k": 2, "at": 389, "len": 192, "text": "Because owners save more of each dollar than workers, a shift of income towards them can open a demand gap.", "say": "Because owners save more of each dollar than workers, a shift of income towards them can open a demand gap."}, {"k": 3, "at": 592, "len": 236, "text": "An automation tax funding a basic income narrows that gap, but the best tax rate ranges from 12 to 95 percent, depending on assumptions.", "say": "An automation tax funding a basic income narrows that gap, but the best tax rate ranges from 12 to 95 percent, depending on assumptions."}, {"k": 4, "at": 839, "len": 118, "text": "The honest answer: it depends on parameters we cannot yet measure.", "say": "The honest answer: it depends on parameters we cannot yet measure."}]}, {"id": "india", "chapter": "Chapter 7. India", "from": 8562, "len": 1008, "segs": [{"k": 0, "at": 27, "len": 42, "text": "Finally, India.", "say": "Finally, India."}, {"k": 1, "at": 80, "len": 218, "text": "Using the 2025 Periodic Labour Force Survey, the average Indian worker sits at the 28th percentile of US exposure.", "say": "Using the 2025 Periodic Labour Force Survey, the average Indian worker sits at the twenty-eighth percentile of US exposure."}, {"k": 2, "at": 309, "len": 282, "text": "Only 6 percent of Indian workers hold jobs above the US top-third line, against 33 percent in the US: 14 percent in cities, 3 percent in villages.", "say": "Only six percent of Indian workers hold jobs above the US top-third line, against thirty-three percent in the US. Fourteen percent in cities, three percent in villages."}, {"k": 3, "at": 602, "len": 166, "text": "Exposed jobs pay 65 percent more, but almost all of that gap is education.", "say": "Exposed jobs pay 65 percent more, but almost all of that gap is education."}, {"k": 4, "at": 780, "len": 180, "text": "And even in the most exposed third, half of regular wage workers have no written contract.", "say": "And even in the most exposed third, half of regular wage workers have no written contract."}]}, {"id": "meaning", "chapter": "What it means", "from": 9552, "len": 772, "segs": [{"k": 0, "at": 27, "len": 30, "text": "So, why pay anyone?", "say": "So, why pay anyone?"}, {"k": 1, "at": 68, "len": 118, "text": "In the data and the models, the price of AI alone does not decide.", "say": "In the data and the models, the price of AI alone does not decide."}, {"k": 2, "at": 197, "len": 240, "text": "Pay depends on what AI cannot yet do, on the new tasks it creates, on competition among those who sell it, and on who owns it.", "say": "Pay depends on what AI cannot yet do, on the new tasks it creates, on competition among those who sell it, and on who owns it."}, {"k": 3, "at": 448, "len": 177, "text": "The larger risk is not that wages collapse overnight, but that labour's share of income slowly falls.", "say": "The larger risk is not that wages collapse overnight, but that labour's share of income slowly falls."}, {"k": 4, "at": 636, "len": 83, "text": "How that income is shared is a policy choice.", "say": "How that income is shared is a policy choice."}]}, {"id": "close", "chapter": "", "from": 10306, "len": 611, "segs": [{"k": 0, "at": 30, "len": 282, "text": "Every chart here is live on the website, where you can move the assumptions, switch the data, and ask the built-in assistant about any concept.", "say": "Every chart here is live on the website, where you can move the assumptions, switch the data, and ask the built-in assistant about any concept."}, {"k": 1, "at": 323, "len": 168, "text": "The full report, the data pipeline and the code are linked there too. Thank you for watching.", "say": "The full report, the data pipeline and the code are linked there too. Thank you for watching."}]}]};
